// Meliora Gym — point opérations du lundi
// Généré par n8n/scripts/build.mjs : modifiez n8n/templates/*.html ou n8n/scripts/n8n-code.mjs,
// puis `npm run build` et réimportez le workflow.
const TEMPLATES = {"operationsDigest":"<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"color-scheme\" content=\"light only\">\n<meta name=\"supported-color-schemes\" content=\"light only\">\n<title>{{subject}}</title>\n<style>\n  @media (max-width: 620px) {\n    .container { width: 100% !important; }\n    .px { padding-left: 22px !important; padding-right: 22px !important; }\n    .h1 { font-size: 25px !important; }\n  }\n  a { color: #E10600; }\n</style>\n</head>\n<body style=\"margin:0;padding:0;background:#f1f1f1;-webkit-text-size-adjust:100%;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;\">{{preheader}}</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background:#f1f1f1;\">\n  <tr>\n    <td align=\"center\" style=\"padding:24px 12px;\">\n      <table role=\"presentation\" class=\"container\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:600px;max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden;\">\n        <tr>\n          <td class=\"px\" style=\"background:#0b0b0c;padding:20px 32px;\">\n            <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n              <tr>\n                <td style=\"vertical-align:middle;\">\n                  <a href=\"{{websiteUrl}}\" style=\"text-decoration:none;\"><img src=\"{{logoUrl}}\" width=\"56\" height=\"56\" alt=\"Meliora Gym\" style=\"display:block;width:56px;height:56px;border:0;border-radius:10px;background:#ffffff;\"></a>\n                </td>\n                <td align=\"right\" style=\"vertical-align:middle;font-family:Arial,Helvetica,sans-serif;font-size:13px;font-weight:bold;letter-spacing:4px;text-transform:uppercase;color:#ffffff;\">\n                  Meliora <span style=\"color:#E10600;\">Gym</span>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n        <tr><td style=\"height:4px;line-height:4px;font-size:0;background:#E10600;\">&nbsp;</td></tr>\n        <tr>\n          <td class=\"px\" style=\"padding:36px 40px 30px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.6;color:#1b1b1b;\">\n<p style=\"margin:0 0 8px;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#E10600;\">Opérations · semaine du {{weekLabel}}</p>\n<h1 class=\"h1\" style=\"margin:0 0 18px;font-family:'Arial Black',Arial,Helvetica,sans-serif;font-size:30px;line-height:1.2;color:#0b0b0c;\">Votre point hebdomadaire</h1>\n<h2 style=\"margin:28px 0 10px;font-size:18px;line-height:1.3;color:#0b0b0c;\">Prospects à relancer ({{leadsCount}})</h2>\n{{{leadsHtml}}}\n<h2 style=\"margin:28px 0 10px;font-size:18px;line-height:1.3;color:#0b0b0c;\">Stock bas ({{stockCount}})</h2>\n{{{stockHtml}}}\n<h2 style=\"margin:28px 0 10px;font-size:18px;line-height:1.3;color:#0b0b0c;\">Maintenance prévue sous 7 jours ({{maintenanceCount}})</h2>\n{{{maintenanceHtml}}}\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:28px 0 10px;\"><tr><td style=\"border-radius:8px;background:#E10600;\"><a href=\"{{adminUrl}}\" style=\"display:inline-block;padding:14px 28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;\">Ouvrir l’administration</a></td></tr></table>\n          </td>\n        </tr>\n        <tr>\n          <td class=\"px\" style=\"background:#0b0b0c;padding:26px 32px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#bdbdbd;\">\n            <strong style=\"color:#ffffff;font-size:13px;letter-spacing:1px;\">MELIORA GYM</strong><br>\n            {{address}}{{#if phone}} · {{phone}}{{/if}}<br>\n            <a href=\"{{instagramUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Instagram {{instagramHandle}}</a>\n            &nbsp;·&nbsp; <a href=\"{{mapsUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Itinéraire</a>\n            &nbsp;·&nbsp; <a href=\"{{websiteUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Site web</a>\n            {{#if footerNote}}<p style=\"margin:14px 0 0;color:#8c8c8c;\">{{footerNote}}</p>{{/if}}\n            <p style=\"margin:14px 0 0;color:#6f6f6f;\">© {{year}} Meliora Gym — Sousse, Tunisie</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>\n"};

const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || value === '' ? fallback : String(value);
  } catch (error) {
    return fallback; // N8N_BLOCK_ENV_ACCESS_IN_NODE=true
  }
};
const BRAND = {
  logoUrl: env('MELIORA_LOGO_URL', 'https://meliora-gym.tn/images/logo.jpg'),
  websiteUrl: env('MELIORA_WEBSITE_URL', 'https://meliora-gym.tn'),
  appUrl: env('MELIORA_APP_URL', 'https://meliora-gym.tn/app'),
  adminUrl: env('MELIORA_ADMIN_URL', 'https://meliora-gym.tn/admin'),
  mapsUrl: env('MELIORA_MAPS_URL', 'https://maps.app.goo.gl/CVWB98nx2RdSd8Mw8'),
  instagramUrl: 'https://www.instagram.com/gymmeliora/',
  instagramHandle: '@gymmeliora',
  address: 'Khzema Est, Rue Colonel Garnaoui, Sousse 4051',
  phone: env('MELIORA_GYM_PHONE'),
};
const FROM = env('MELIORA_FROM_EMAIL', 'Meliora Gym <contact@meliora-gym.tn>');
const OWNER = env('MELIORA_OWNER_EMAIL');
const STAFF = env('MELIORA_STAFF_EMAIL', OWNER);
const MEMBER_NOTE = 'Vous recevez cet e-mail car vous êtes membre de Meliora Gym. Répondez « STOP » pour ne plus recevoir nos messages.';
const TZ = 'Africa/Tunis';

const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
// {{#if key}}…{{/if}} blocks, then {{{raw}}} / {{escaped}} values in a single pass (values are never re-scanned).
const render = (template, vars) =>
  template
    .replace(/\{\{#if (\w+)\}\}([\s\S]*?)\{\{\/if\}\}/g, (_, key, inner) => (vars[key] ? inner : ''))
    .replace(/\{\{\{(\w+)\}\}\}|\{\{(\w+)\}\}/g, (_, raw, key) => (raw ? String(vars[raw] ?? '') : esc(vars[key])));

const asDate = (value) =>
  typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? new Date(`${value}T12:00:00Z`) : new Date(value);
const fmt = (value, options) => {
  if (!value) return '';
  const date = asDate(value);
  return Number.isNaN(date.getTime()) ? String(value) : new Intl.DateTimeFormat('fr-FR', { timeZone: TZ, ...options }).format(date);
};
const longDate = (value) => fmt(value, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const dayMonth = (value) => fmt(value, { weekday: 'long', day: 'numeric', month: 'long' });
const shortDate = (value) => fmt(value, { day: 'numeric', month: 'long', year: 'numeric' });
const dateTime = (value) => fmt(value, { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const hour = (value) => fmt(value, { hour: '2-digit', minute: '2-digit' });
const dayKey = (value) => fmt(value, { year: 'numeric', month: '2-digit', day: '2-digit' }).split('/').reverse().join('-');
const capitalize = (text) => (text ? text.charAt(0).toUpperCase() + text.slice(1) : '');
const money = (amount) =>
  `${Number(amount || 0).toLocaleString('fr-FR', { minimumFractionDigits: 3, maximumFractionDigits: 3 })} DT`;
const plural = (count, one, many) => `${count} ${Math.abs(Number(count)) === 1 ? one : many}`;
const firstWord = (name) => String(name || '').trim().split(/\s+/)[0] || '';
const weekRange = (from, to) => `${fmt(from, { day: 'numeric', month: 'long' })} au ${fmt(to, { day: 'numeric', month: 'long', year: 'numeric' })}`;

const METHODS = { CASH: 'Espèces', CARD: 'Carte bancaire', TRANSFER: 'Virement bancaire', D17: 'D17' };
const SOURCES = {
  WALK_IN: 'Passage à l’accueil',
  INSTAGRAM: 'Instagram',
  FACEBOOK: 'Facebook',
  WEBSITE: 'Site web',
  REFERRAL: 'Parrainage',
  PHONE: 'Téléphone',
  OTHER: 'Autre',
};
const PRIORITIES = { LOW: 'basse', MEDIUM: 'moyenne', HIGH: 'haute', URGENT: 'urgente' };

/** One e-mail item for the "Send Email" node, or null when there is no usable recipient. */
const email = (template, { to, subject, preheader = '', vars = {}, footerNote = '' }) => {
  const recipient = String(to || '').trim();
  if (!recipient.includes('@')) return null;
  const html = render(TEMPLATES[template], {
    ...BRAND,
    year: new Date().getFullYear(),
    subject,
    preheader,
    footerNote,
    ...vars,
  });
  return { json: { from: FROM, to: recipient, subject, html } };
};

/** Bordered list used in owner digests: rows of { title, detail }. */
const listTable = (rows, empty = 'Rien à signaler ✅') => {
  if (!rows.length) return `<p style="margin:0 0 14px;color:#2e7d32;">${esc(empty)}</p>`;
  const body = rows
    .map(
      (row) =>
        `<tr><td style="padding:11px 16px;border-bottom:1px solid #f1f1f1;font-size:14px;"><strong style="color:#0b0b0c;">${esc(row.title)}</strong>` +
        (row.detail ? `<br><span style="color:#6b6b6b;font-size:13px;">${esc(row.detail)}</span>` : '') +
        '</td></tr>',
    )
    .join('');
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 18px;border:1px solid #ececec;border-radius:10px;border-collapse:separate;border-spacing:0;">${body}</table>`;
};

const pick = (name) =>
  $(name)
    .all()
    .map((item) => item.json)
    .filter((row) => row && row.id);
const leads = pick('Prospects à relancer');
const products = pick('Stock bas');
const equipment = pick('Maintenance à prévoir');
const now = new Date();

const leadsHtml = listTable(
  leads.map((lead) => ({
    title: `${lead.firstName ?? ''} ${lead.lastName ?? ''}`.trim(),
    detail: [
      lead.phone,
      SOURCES[lead.source] ?? lead.source,
      lead.status === 'TRIAL' ? 'séance d’essai' : null,
      lead.followUpAt ? `relance prévue le ${shortDate(lead.followUpAt)}` : null,
      lead.assignedToName ? `suivi par ${lead.assignedToName}` : null,
    ]
      .filter(Boolean)
      .join(' · '),
  })),
);
const stockHtml = listTable(
  products.map((product) => ({
    title: product.name,
    detail: `${plural(product.stock ?? 0, 'unité', 'unités')} en stock · seuil ${product.lowStockThreshold}`,
  })),
);
const maintenanceHtml = listTable(
  equipment.map((item) => ({
    title: item.name,
    detail: [
      item.roomName,
      item.nextMaintenanceAt ? `entretien prévu le ${shortDate(item.nextMaintenanceAt)}` : null,
      item.status === 'OUT_OF_ORDER' ? 'hors service' : item.status === 'MAINTENANCE' ? 'en maintenance' : null,
    ]
      .filter(Boolean)
      .join(' · '),
  })),
);

const weekLabel = weekRange(now, new Date(now.getTime() + 6 * 86_400_000));
const out = email('operationsDigest', {
  to: OWNER,
  subject: `Point opérations Meliora — semaine du ${weekLabel}`,
  preheader: `${plural(leads.length, 'prospect', 'prospects')} à relancer · ${plural(products.length, 'produit', 'produits')} en stock bas · ${plural(equipment.length, 'entretien', 'entretiens')}`,
  vars: {
    weekLabel,
    leadsCount: leads.length,
    leadsHtml,
    stockCount: products.length,
    stockHtml,
    maintenanceCount: equipment.length,
    maintenanceHtml,
  },
});
return out ? [out] : [];
